mapper.sql:
WHERE 1=1
AND s.factory_id=#{reviewQueryDTO.factory}
AND s.id=#{reviewQueryDTO.skuId}
AND s.asset_type=#{reviewQueryDTO.assetType}
AND (LOCATE(#{reviewQueryDTO.keyword},CONVERT(a.id USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{reviewQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{reviewQueryDTO.keyword},s.prop_name)>0)
AND LOCATE(#{reviewQueryDTO.factoryKeyword},f.factory_name)>0

mapper.select:
SELECT id, action_type, applicant_name, apply_remark, asset_type, audit_status, factory_id, factory_name, initial_quantity, prop_name, quantity, quantity_delta, related_sku_audit_id, reviewed_at, sku_code, sku_id, source_type, submitted_at, version

 AND audit_status=#{reviewQueryDTO.status}
 ORDER BY submitted_at DESC,id DESC,source_type ASC LIMIT #{reviewQueryDTO.limit} OFFSET #{reviewQueryDTO.offset}
